package com.ems.repository; import com.ems.model.*; import org.springframework.data.jpa.repository.JpaRepository; import java.time.LocalDate; import java.util.*; public interface LeaveRequestRepository extends JpaRepository<LeaveRequest,Long>{ List<LeaveRequest> findByEmployeeEmployeeIdOrderByCreatedAtDesc(String id); List<LeaveRequest> findByStatusOrderByCreatedAtAsc(LeaveStatus s); List<LeaveRequest> findByStatusAndStartDateLessThanEqualAndEndDateGreaterThanEqual(LeaveStatus s, LocalDate end, LocalDate start); }
